-- Dictionary baseline. Lead category/source data intentionally excluded.
SET NAMES utf8mb4;

', '1', '2023-01-26 09:53:49', '1', '2023-01-26 16:36:14', b'0');
', '1', '2023-07-19 20:08:06', '1', '2023-07-19 20:09:08', b'0');
SELECT seed.sort,seed.label,seed.value,seed.dict_type,0,'1',NOW(),'1',NOW(),b'0' FROM (
SELECT 1 sort,'电话' label,'phone' value,'zsjos_lead_follow_up_method' dict_type UNION ALL SELECT 2,'微信','wechat','zsjos_lead_follow_up_method' UNION ALL SELECT 3,'短信','sms','zsjos_lead_follow_up_method' UNION ALL SELECT 4,'上门','visit','zsjos_lead_follow_up_method' UNION ALL SELECT 5,'其他','other','zsjos_lead_follow_up_method' UNION ALL
SELECT 1,'已联系有意向','interested','zsjos_lead_follow_up_result' UNION ALL SELECT 2,'已联系待考虑','considering','zsjos_lead_follow_up_result' UNION ALL SELECT 3,'已约下次跟进','scheduled_follow_up','zsjos_lead_follow_up_result' UNION ALL SELECT 4,'未联系上','unreachable','zsjos_lead_follow_up_result' UNION ALL SELECT 5,'明确无意向','not_interested','zsjos_lead_follow_up_result' UNION ALL SELECT 6,'其他','other','zsjos_lead_follow_up_result') seed
WHERE NOT EXISTS (SELECT 1 FROM system_dict_data existing WHERE existing.dict_type=seed.dict_type AND existing.value=seed.value AND existing.deleted=b'0');

SELECT seed.sort,seed.label,seed.value,'zsjos_lead_appeal_status',0,seed.color,'1',NOW(),'1',NOW(),b'0' FROM (
SELECT 10 sort,'销售主管复核中' label,'sales_manager_reviewing' value,'warning' color UNION ALL
SELECT 20,'质控复核中','quality_reviewing','warning' UNION ALL
SELECT 30,'董事长终审中','chairman_reviewing','warning' UNION ALL
SELECT 40,'已改判有效','overturned','success' UNION ALL
SELECT 50,'维持无效','upheld','danger' UNION ALL
SELECT 60,'已撤回','withdrawn','default') seed
WHERE NOT EXISTS (SELECT 1 FROM system_dict_data existing WHERE existing.dict_type='zsjos_lead_appeal_status' AND existing.value=seed.value AND existing.deleted=b'0');

